{"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立世界观规则，林晚为躲避霸凌触发透明规则，首次进入透明层遇见陆沉，发现他能被看见但无法触碰",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "监控死角",
        "core_event": "林晚被赵婷等人追堵，逃入教学楼监控死角，故意停留超过3分钟触发透明规则",
        "emotional_tone": "压抑、紧张、绝望",
        "key_scenes": ["走廊被追堵", "逃入死角", "倒计时3分钟", "身体逐渐透明"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "透明层",
        "core_event": "林晚进入透明状态，发现能看见另一个世界，第一次看见陆沉站在她面前",
        "emotional_tone": "震惊、疑惑、恐惧",
        "key_scenes": ["透明视角下的世界", "看见模糊人影", "陆沉现身", "初次对视"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "他说话了",
        "core_event": "陆沉对林晚说话，她震惊地发现他能被看见也能被听见，但他以为她听不见",
        "emotional_tone": "震撼、悸动、酸涩",
        "key_scenes": ["陆沉轻声说话", "林晚听见声音", "他讲述三年孤独", "她无法回应"]
      }
    ],
    "turning_point": "林晚发现陆沉是三年前失踪的学霸，他被困在透明层三年，而她只有24小时"
  },
  "act_two": {
    "description": "林晚与陆沉在透明层相处，情感逐渐加深，陆沉讲述被困真相，林晚发现规则的残酷——24小时后她会忘记一切",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "三年的时间",
        "core_event": "陆沉讲述三年前如何触发规则被困，以及这三年来他每天对林晚说话的故事",
        "emotional_tone": "悲伤、温柔、心疼",
        "key_scenes": ["三年前的回忆", "每天对她说话", "她从未回应", "他从未放弃"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "无法触碰",
        "core_event": "林晚试图触碰陆沉，发现透明层的人无法被触碰，两人之间隔着无形的墙",
        "emotional_tone": "绝望、无力、痛楚",
        "key_scenes": ["伸手触碰", "指尖穿过", "他苦笑", "她流泪"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "规则的代价",
        "core_event": "陆沉告诉林晚规则的代价——24小时后她会忘记这24小时发生的一切，包括他",
        "emotional_tone": "震惊、崩溃、绝望",
        "key_scenes": ["陆沉说出真相", "林晚崩溃", "他安慰她", "时间流逝的倒计时"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "最后的时光",
        "core_event": "两人决定珍惜剩余时间，陆沉带林晚看透明层里的世界，讲述他这三年的观察",
        "emotional_tone": "温柔、苦涩、珍惜",
        "key_scenes": ["透明层风景", "他眼中的世界", "她眼中的他", "无声的告白"]
      }
    ],
    "turning_point": "林晚意识到陆沉三年来一直在等她，而她是唯一一个能看见他的人，但她注定会忘记"
  },
  "act_three": {
    "description": "24小时即将结束，林晚与陆沉告别，她选择记住一些东西，但规则不可违抗，最终她忘记一切回到现实，而他继续等待",
    "key_chapters": [
      {
        "chapter_number": 8,
        "chapter_title": "告别",
        "core_event": "24小时倒计时结束前，陆沉对林晚说出最后的告白，林晚在消失前拼命想要记住他的脸",
        "emotional_tone": "撕心裂肺、绝望、深情",
        "key_scenes": ["最后告白", "她拼命记忆", "他微笑告别", "时间归零"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "忘记",
        "core_event": "林晚回到现实，忘记了一切，只感觉心里空了一块。苏晓找到她，问她去哪了。她回头看向监控死角，莫名流泪",
        "emotional_tone": "空洞、怅然、BE美学",
        "key_scenes": ["恢复实体", "记忆空白", "苏晓寻找", "回头流泪", "他仍在等待"]
      }
    ],
    "turning_point": "林晚忘记了一切，但陆沉仍在透明层等待下一个能看见他的人——或许永远等不到，或许明天就会有人来"
  }
}"}

